mapper.select:
select t.space_id,t.space_id spaceId,t.csp_id,t.csp_id cspId,t.time_id,t.time_id timeId,t.order_id,t.order_id
orderId,t.remark,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId,
t.received_amount,t.received_amount receivedAmount,t.pay_way,t.pay_way payWay,t.pay_time,t.pay_time payTime,
t.verify_method,t.verify_method verifyMethod,t.verifier_id,t.verifier_id
verifierId,t.verifier_name,t.verifier_name verifierName,
cs.name spaceName,csp.person_name personName,csp.person_tel personTel,csp.appointment_time appointmentTime,
csp.order_id cspOrderId,csp.receivable_amount receivableAmount,csp.received_amount receivedAmountPerson,
csp.pay_way payWayPerson,csp.state state,td2.name stateName,
cspt.hours,t.create_time createTime,cv.`name` venueName
from community_space_confirm_order t
left join community_space_person_time cspt on t.time_id = cspt.time_id and cspt.status_cd = '0'
left join community_space_person csp on t.csp_id = csp.csp_id and csp.status_cd = '0'
left join community_space cs on csp.space_id = cs.space_id and cs.status_cd = '0'
left join community_venue cv on cs.venue_id = cv.venue_id and cv.status_cd = '0'
left join t_dict td2 on csp.state = td2.status_cd and td2.table_name = 'community_space_person' and td2.table_columns = 'state'
where 1 =1

    and csp.person_name like concat('%',#{personName},'%')


    and csp.person_tel = #{personTel}


    and csp.appointment_time = #{appointmentTime}


    and t.space_id= #{spaceId}


    and t.csp_id= #{cspId}


    and t.time_id= #{timeId}


    and t.order_id= #{orderId}


    and t.verify_method= #{verifyMethod}


    and t.remark= #{remark}


    and (t.order_id like concat('%',#{keyword},'%') or csp.order_id like concat('%',#{keyword},'%')
    or csp.person_name like concat('%',#{keyword},'%') or csp.person_tel like concat('%',#{keyword},'%'))


    and t.create_time >= #{beginTime}


    and t.create_time <= concat(#{endTime},' 23:59:59')


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update community_space_confirm_order t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.space_id= #{spaceId}


    , t.csp_id= #{cspId}


    , t.time_id= #{timeId}


    , t.remark= #{remark}


    , t.received_amount= #{receivedAmount}


    , t.pay_way= #{payWay}


    , t.pay_time= #{payTime}


    , t.verify_method= #{verifyMethod}


    , t.verifier_id= #{verifierId}


    , t.verifier_name= #{verifierName}


    , t.community_id= #{communityId}

where 1=1

    and t.order_id= #{orderId}


    and t.time_id= #{timeId}


    and t.csp_id= #{cspId}


    and t.community_id= #{communityId}

mapper.select:
select count(1) count
from community_space_confirm_order t
left join community_space_person_time cspt on t.time_id = cspt.time_id and cspt.status_cd = '0'
left join community_space_person csp on t.csp_id = csp.csp_id and csp.status_cd = '0'
left join community_space cs on csp.space_id = cs.space_id and cs.status_cd = '0'
left join community_venue cv on cs.venue_id = cv.venue_id and cv.status_cd = '0'
where 1 =1

    and csp.person_name like concat('%',#{personName},'%')


    and csp.person_tel = #{personTel}


    and csp.appointment_time = #{appointmentTime}


    and t.space_id= #{spaceId}


    and t.csp_id= #{cspId}


    and t.time_id= #{timeId}


    and t.order_id= #{orderId}


    and t.verify_method= #{verifyMethod}


    and t.remark= #{remark}


    and (t.order_id like concat('%',#{keyword},'%') or csp.order_id like concat('%',#{keyword},'%')
    or csp.person_name like concat('%',#{keyword},'%') or csp.person_tel like concat('%',#{keyword},'%'))


    and t.create_time >= #{beginTime}


    and t.create_time <= concat(#{endTime},' 23:59:59')


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}

select ifnull(sum(case when date(t.create_time) = curdate() then 1 else 0 end), 0) todayCount, ifnull(sum(case when date(t.create_time) = curdate() then ifnull(csp.receivable_amount, t.received_amount) else 0 end), 0) todayAmount, count(1) totalCount from community_space_confirm_order t left join community_space_person csp on t.csp_id = csp.csp_id and csp.status_cd = '0' where 1 = 1
and t.status_cd= #{statusCd}
and t.community_id= #{communityId}
